#!/usr/bin/env bash
# =====================================================================
# run_stage1_chain_regression.sh
# ------------------------------------------------------------------
# Stage-1 RTL regression for the xfft-FREE timing + fractional-CFO chain
# (rtl/frac_cfo_frame_corrector_top.v) over the bit-accurate vector grid
# in vectors/shared_bitacc/  (generated by gen_shared_vectors_bitacc.py).
#
# Pure python3 + iverilog 11.0 -- NO Vivado / xsim.
#
# For each testcase it drives tb/frac_cfo_frame_corrector_top_param_tb.sv
# under iverilog with that tc's input.hex and checks the chain's
#     frame_start (frame_index)  +/-1
#     peak_lag                   +/-1
#     |frac_phase|               magnitude, quantized tolerance
# against the python golden (expected.json). detection_ok=false cases
# (heavily attenuated low-scale vectors that the energy detector cannot
# arm on) are SKIPPED gracefully.
#
# Output:
#   sim_out/stage1_chain_regression/<tc>_sim.log   per-tc transcript
#   sim_out/stage1_chain_regression/gate.txt       gate summary
# Prints per-tc PASS/FAIL and a final:
#   GATE_STAGE1_CHAIN_REGRESSION: PASS|FAIL (P/N)
# Exit 0 iff all run (non-skipped) testcases pass.
# =====================================================================
set -uo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
cd "${ROOT}"

VEC_DIR="${ROOT}/vectors/shared_bitacc"
TB="${ROOT}/tb/frac_cfo_frame_corrector_top_param_tb.sv"
OUT="${ROOT}/sim_out/stage1_chain_regression"
mkdir -p "${OUT}"

# Per-tc tolerances (frame/peak per the plan; frac magnitude quantized).
# frame_start is +/-1; peak_lag is per-vector (peak_tol in expected.json:
# +/-1 normally, widened only for flagged low-amplitude / near-floor metric
# vectors -- see gen_shared_vectors_bitacc.py).
FTOL=1     # frame_start +/-1
# Fractional-phase tolerance: the RTL CORDIC/conj path differs from the
# float golden by a few tens of LSB (e.g. golden 3277 -> RTL 3317 == 40 LSB).
# Use an absolute floor plus a relative term so both tiny and large CFOs pass.
QFLOOR=160

if [[ ! -d "${VEC_DIR}" ]]; then
    echo "[stage1] vectors missing -> generating ${VEC_DIR}"
    python3 "${SCRIPT_DIR}/gen_shared_vectors_bitacc.py" || exit 2
fi

RTL=rtl
TIMING_DEPS="$RTL/streaming_cp_autocorr.v $RTL/delay_sample.v $RTL/complex_mult.v \
$RTL/moving_avg_optimized.v $RTL/sample_power_sq.v $RTL/complex_to_mag.v \
$RTL/delayT.v $RTL/ram_2port.v"
FRAC_DEPS="$RTL/frac_cfo_estimator.v $RTL/cordic_atan2.v"
CORR_DEPS="$RTL/frac_cfo_corrector_top.v $RTL/nco_phase_gen.v $RTL/complex_rotator.v $RTL/complex_mult_iq.v"

VVP="${OUT}/stage1.vvp"
echo "==== [compile] frac_cfo_frame_corrector_top_param_tb ===="
if ! iverilog -g2012 -o "${VVP}" \
    $RTL/frac_cfo_frame_corrector_top.v $RTL/iq_frame_buffer.v $RTL/iq_capture_pingpong.v \
    $RTL/frame_detector.v $RTL/frame_detect_fsm.v $RTL/sliding_window_sum.v \
    $RTL/frame_frac_cfo_top.v $RTL/timing_sync_top.v $RTL/peak_detector.v \
    $TIMING_DEPS $FRAC_DEPS $CORR_DEPS \
    "${TB}" 2>"${OUT}/compile.log"; then
    grep -iE "error" "${OUT}/compile.log" | head
    echo "GATE_STAGE1_CHAIN_REGRESSION: FAIL (compile)" | tee "${OUT}/gate.txt"
    exit 2
fi
echo "  compiled OK -> ${VVP}"

# enumerate testcases (sorted)
mapfile -t TCS < <(ls -d "${VEC_DIR}"/tc???? 2>/dev/null | sort)
TOTAL=${#TCS[@]}
if [[ ${TOTAL} -eq 0 ]]; then
    echo "GATE_STAGE1_CHAIN_REGRESSION: FAIL (no vectors)" | tee "${OUT}/gate.txt"
    exit 2
fi

pass=0; fail=0; skip=0; run=0
FAILED_LIST=""

echo ""
echo "==== [run] ${TOTAL} testcases from ${VEC_DIR} ===="
printf "%-8s %-10s %-5s %-9s %-9s %-9s  %s\n" \
    TC MODE DET "fs(g)" "pk(g)" "|fq|(g)" RESULT

for tcdir in "${TCS[@]}"; do
    tc="$(basename "${tcdir}")"
    exp="${tcdir}/expected.json"
    hex="${tcdir}/input.hex"
    [[ -f "${exp}" && -f "${hex}" ]] || { echo "${tc}: missing files"; fail=$((fail+1)); continue; }

    # extract golden fields via python (robust to nulls)
    read -r DETOK NSAMP GFS GPK GFQ MODE QTOL PTOL < <(python3 - "${exp}" "${QFLOOR}" <<'PY'
import json, sys
exp = json.load(open(sys.argv[1]))
qfloor = int(sys.argv[2])
det = 1 if exp.get("detection_ok") else 0
ns  = exp.get("num_samples") or 4160
fs  = exp.get("golden_frame_start")
pk  = exp.get("golden_peak_index")
fq  = exp.get("golden_frac_phase_q16")
fq  = 0 if fq is None else abs(int(fq))
fs  = -1 if fs is None else int(fs)
pk  = -1 if pk is None else int(pk)
ptol = int(exp.get("peak_tol", 1))   # per-vector peak_lag tol (widened low-scale)
# adaptive frac tol: floor + 6% of magnitude (covers CORDIC/conj LSB drift)
qtol = max(qfloor, int(round(0.06*fq)) + 50)
print(det, ns, fs, pk, fq, exp.get("mode","?"), qtol, ptol)
PY
)

    if [[ "${DETOK}" == "0" ]]; then
        printf "%-8s %-10s %-5s %-9s %-9s %-9s  %s\n" \
            "${tc}" "${MODE}" "no" "-" "-" "-" "SKIP(det)"
        skip=$((skip+1))
        echo "${tc}: SKIP detection_ok=false" >"${OUT}/${tc}_sim.log"
        continue
    fi

    run=$((run+1))
    log="${OUT}/${tc}_sim.log"
    vvp "${VVP}" \
        +HEX="${hex}" +NSAMP="${NSAMP}" \
        +GFS="${GFS}" +GPK="${GPK}" +GFQ="${GFQ}" \
        +FTOL="${FTOL}" +PTOL="${PTOL}" +QTOL="${QTOL}" \
        >"${log}" 2>&1

    rline="$(grep -E '^STAGE1_TC_RESULT' "${log}" | tail -1)"
    pf="$(sed -n 's/.*pass=\([0-9]\).*/\1/p' <<<"${rline}")"

    if [[ "${pf}" == "1" ]]; then
        printf "%-8s %-10s %-5s %-9s %-9s %-9s  %s\n" \
            "${tc}" "${MODE}" "yes" "${GFS}" "${GPK}" "${GFQ}" "PASS"
        pass=$((pass+1))
    else
        printf "%-8s %-10s %-5s %-9s %-9s %-9s  %s\n" \
            "${tc}" "${MODE}" "yes" "${GFS}" "${GPK}" "${GFQ}" "FAIL"
        # surface the mismatch reason
        grep -E '^\[CHK-FAIL\]|^\[RESULT\] (frame|peak|frac|out)' "${log}" | sed 's/^/        /'
        fail=$((fail+1))
        FAILED_LIST="${FAILED_LIST} ${tc}"
    fi
done

echo ""
echo "========================================================================"
echo "STAGE-1 CHAIN REGRESSION (xfft-free timing + fractional-CFO)"
echo "  total=${TOTAL}  run=${run}  pass=${pass}  fail=${fail}  skip=${skip}(low-scale)"
[[ -n "${FAILED_LIST}" ]] && echo "  failed:${FAILED_LIST}"
GATE="GATE_STAGE1_CHAIN_REGRESSION: $([[ ${fail} -eq 0 ]] && echo PASS || echo FAIL) (${pass}/${run})"
echo "${GATE}"
echo "========================================================================"

{
    echo "${GATE}"
    echo "total=${TOTAL} run=${run} pass=${pass} fail=${fail} skip=${skip}"
    echo "vectors=${VEC_DIR}"
    echo "tb=tb/frac_cfo_frame_corrector_top_param_tb.sv"
    echo "tolerances: frame=+/-${FTOL} peak=per-vector(+/-1, low-scale widened) frac=floor${QFLOOR}+6%"
    [[ -n "${FAILED_LIST}" ]] && echo "failed:${FAILED_LIST}"
    echo "NOTE: xfft-free Stage-1 slice (frame_start/peak_lag/frac_cfo)."
    echo "      integer-CFO (k_int) decode still requires xfft/xsim."
} >"${OUT}/gate.txt"

[[ ${fail} -eq 0 ]] && exit 0 || exit 1
